package io.github.ddxpromax.webcoder.checkpoint;

import io.github.ddxpromax.webcoder.agent.HarnessAgentFactory;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api") @CrossOrigin(origins = "*")
public class CheckpointController {
    private final CheckpointService checkpoints; private final HarnessAgentFactory agents;
    public CheckpointController(CheckpointService checkpoints, HarnessAgentFactory agents) { this.checkpoints = checkpoints; this.agents = agents; }
    @GetMapping("/workspace/checkpoints/status") public ResponseEntity<?> status(@RequestHeader(value="X-Agent-Id", required=false) String agent) { try { var workspace = agents.workspaceFor(agentId(agent)); var graph = checkpoints.graph(workspace, 1); return ResponseEntity.ok(Map.of("auto_enabled", false, "has_checkpoints", !graph.isEmpty(), "workspace_dir", workspace.toString())); } catch (Exception e) { return fail(e); } }
    @GetMapping("/workspace/checkpoints/graph") public ResponseEntity<?> graph(@RequestParam(defaultValue="500") int limit, @RequestHeader(value="X-Agent-Id", required=false) String agent) { try { List<Map<String,Object>> nodes = checkpoints.graph(agents.workspaceFor(agentId(agent)), limit); return ResponseEntity.ok(Map.of("nodes", nodes, "sessions", List.of(), "summary", Map.of("total", nodes.size(), "auto", 0, "snapshots", nodes.size(), "safety", 0, "heads", nodes.isEmpty()?0:1), "truncated", false)); } catch (Exception e) { return fail(e); } }
    @PostMapping("/workspace/checkpoints/snapshot") public ResponseEntity<?> snapshot(@RequestBody Map<String,Object> body, @RequestHeader(value="X-Agent-Id", required=false) String agent) { String session = String.valueOf(body.getOrDefault("session_id", "")); if (session.isBlank()) return ResponseEntity.badRequest().body(Map.of("detail", "session_id is required")); try { return ResponseEntity.ok(checkpoints.snapshot(agents.workspaceFor(agentId(agent)), session, String.valueOf(body.getOrDefault("user_id", "")), String.valueOf(body.getOrDefault("channel", "console")), String.valueOf(body.getOrDefault("name", "")))); } catch (Exception e) { return fail(e); } }
    @PostMapping("/workspace/checkpoints/restore/preview") public ResponseEntity<?> preview(@RequestBody Map<String,Object> body, @RequestHeader(value="X-Agent-Id", required=false) String agent) { String commit = String.valueOf(body.getOrDefault("commit", "")); if (commit.length() < 7) return ResponseEntity.badRequest().body(Map.of("detail", "commit is required (min 7 chars)")); try { return ResponseEntity.ok(Map.of("target", commit, "commit", commit, "restored_paths", checkpoints.changedPaths(agents.workspaceFor(agentId(agent)), commit), "deleted_paths", List.of(), "file_paths", List.of(), "pre_restore_ref", "", "dry_run", true, "include_memory", Boolean.TRUE.equals(body.get("include_memory")), "include_files", Boolean.TRUE.equals(body.get("include_files")))); } catch (Exception e) { return fail(e); } }
    @PostMapping("/workspace/checkpoints/restore") public ResponseEntity<?> restore(@RequestBody Map<String,Object> body, @RequestHeader(value="X-Agent-Id", required=false) String agent) { String commit = String.valueOf(body.getOrDefault("commit", "")); if (commit.length() < 7) return ResponseEntity.badRequest().body(Map.of("detail", "commit is required (min 7 chars)")); @SuppressWarnings("unchecked") List<String> paths = body.get("files") instanceof List<?> raw ? raw.stream().map(String::valueOf).toList() : List.of(); try { return ResponseEntity.ok(Map.of("target", commit, "commit", commit, "restored_paths", checkpoints.restore(agents.workspaceFor(agentId(agent)), commit, paths), "deleted_paths", List.of(), "file_paths", paths, "pre_restore_ref", "", "dry_run", false)); } catch (Exception e) { return fail(e); } }
    @PostMapping("/workspace/checkpoints/gc/preview") public ResponseEntity<?> gcPreview(@RequestBody(required=false) Map<String,Object> body, @RequestHeader(value="X-Agent-Id", required=false) String agent) { return gc(body, agent, true); }
    @PostMapping("/workspace/checkpoints/gc") public ResponseEntity<?> gcApply(@RequestBody(required=false) Map<String,Object> body, @RequestHeader(value="X-Agent-Id", required=false) String agent) { return gc(body, agent, false); }
    @DeleteMapping("/workspace/checkpoints") public ResponseEntity<?> reset(@RequestHeader(value="X-Agent-Id", required=false) String agent) { try { checkpoints.reset(agents.workspaceFor(agentId(agent))); return ResponseEntity.ok(Map.of("reset", true, "auto_enabled", false)); } catch (Exception e) { return fail(e); } }
    private String agentId(String id) { return id == null || id.isBlank() ? "default" : id; }
    private ResponseEntity<?> gc(Map<String,Object> body, String agent, boolean dry) { int keep = body != null && body.get("keep_count") instanceof Number n ? n.intValue() : 20; try { List<String> deleted = checkpoints.gc(agents.workspaceFor(agentId(agent)), dry, keep); return ResponseEntity.ok(Map.of("deleted_refs", deleted, "kept_refs", List.of(), "dry_run", dry)); } catch (Exception e) { return fail(e); } }
    private ResponseEntity<Map<String,String>> fail(Exception e) { return ResponseEntity.badRequest().body(Map.of("detail", e.getMessage() == null ? "checkpoint failed" : e.getMessage())); }
}
